import logging
import subprocess

from robot.libraries.BuiltIn import BuiltIn
from taf.transport.ssh import ssh
from taf.nms.netact import netact as netact_interface

from taf.rfrl.csv4all.resources.node.feature.netact.decorators import retry
from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import NotValidNetact

logging.getLogger('taf.nms.netact.ssh_node').setLevel(logging.CRITICAL)


class Netact:
    def __init__(self, name: str, username: str = "omc", password: str = "Medsql!_1893", security_mode: str = "no TLS",
                 ip_version: str = "IPv4", certificate_type: str = "Already installed",
                 maintenance_region: str = "MRC-COMMON/MR-COMMON", cmp_name: str = None, netact_host_ip: str = None):
        self.rollback_sw_timeout = 1200
        self.activate_sw_timeout = 1800
        self.download_sw_timeout = 21600
        self.provision_sw_timeout = 21600
        self.cm_upload_timeout = 300
        self._ssh = ssh()
        self.netact_name = name
        self.ssh_username = username
        self.ssh_password = password
        self.security_mode = security_mode
        self.ip_version = ip_version
        self.certificate_type = certificate_type
        self.netact_cmp = cmp_name
        self.netact_interface = netact_interface()
        self.other_netacts = ["dallas", "swan"]
        self.netact_host = netact_host_ip or self.get_netact_host()
        self.netact_connection = self.setup_ssh_netact_connection()
        self.__set_netact_nodes()
        self.maintenance_region = maintenance_region
        self.swm_arch_dir = "/var/opt/oss/global/swm/swm_arch/"
        self.swm_temp_dir = "/d/oss/global/swmanager/swm_temp/"

    def is_imported_sw(self, sw_build: str) -> bool:
        sw_gui_exist = self.netact_interface.is_imported(sw_build)
        logging.info(f"Software exists on gui: {sw_gui_exist}")
        sw_ssh_exist = self.netact_connection.files.exists(f"{self.swm_arch_dir}/{sw_build}")
        logging.info(f"Software exists on ssh: {sw_ssh_exist}")
        return sw_gui_exist and sw_ssh_exist

    def integrate_mrbts_with_netact(self, mo_dist_name: str, mplane: str, release: str = None,
                                    security_mode: str = None):
        return self.netact_interface.integrate_mrbts_with_netact(release=release,
                                                                 mr=self.maintenance_region,
                                                                 mrbts_address=mplane,
                                                                 dist_name=mo_dist_name,
                                                                 ip_version=self.ip_version,
                                                                 security_mode=self.security_mode if not
                                                                 security_mode else security_mode)

    def deintegrate_mrbts_from_netact(self, mo_dist_name: str):
        return self.netact_interface.deintegrate_mrbts_from_netact(dist_name=mo_dist_name)

    def setup_netact(self, service="cmwas"):
        self.netact_interface.add_node(service, self.netact_was_node_ip, self.ssh_username, self.ssh_password)
        self.netact_interface.add_web_url(self.netact_web_url, self.ssh_username, self.ssh_password)

    def teardown_netact(self, service="cmwas"):
        self.netact_interface.delete_node(service)
        self.netact_interface.clean_all()

    def import_sw(self, sw_build: str, releases: list, clean_tmp_storage: bool = True):
        return self.netact_interface.import_build(f"{sw_build}.zip", release=releases if releases else None,
                                                  clean_temp_storage=clean_tmp_storage)

    def provision_sw(self, target_sw: str, mo_dist_name: str):
        return self.netact_interface.provision_sw(mo_dist_name, target_sw, timeout=self.provision_sw_timeout)

    def download_sw(self, target_sw: str, mo_dist_name: str):
        return self.netact_interface.download_sw(mo_dist_name, target_sw, timeout=self.download_sw_timeout)

    def activate_sw(self, target_sw: str, mo_dist_name: str):
        return self.netact_interface.activate_sw(mo_dist_name, target_sw, timeout=self.activate_sw_timeout)

    @retry(times=3, delay=30)
    def start_swm_operation(self, operation: str, target_sw: str, mo_dist_name: str):
        return self.netact_interface.start_swm_operation(operation_type=operation, dist_names=mo_dist_name,
                                                         package=target_sw)

    def precheck_sw(self, target_sw: str, mo_dist_name: str, precheck_type: str = "fullCheck"):
        precheck_type = "fullCheck" if precheck_type.lower() == "fullcheck" else precheck_type
        custom_attributes = {'precheckType': precheck_type}
        return self.netact_interface.precheck_sw(dist_names=mo_dist_name, package_name=target_sw,
                                                 custom_attributes=custom_attributes)

    def diagnostic_check(self, mo_dist_name: str):
        return self.netact_interface.run_diagnostic_check(dist_names=mo_dist_name, verbose=True)

    def get_progress_of_swm_operation(self, operation_id: str) -> dict:
        return self.netact_interface.get_progress_of_swm_operation(operation_id=operation_id)

    def rollback_sw(self, mo_dist_name: str):
        return self.netact_interface.rollback_sw(mo_dist_name, timeout=self.rollback_sw_timeout)

    def reset_ne(self, dist_names: str, parameters: dict):
        self.netact_interface.reset_ne(dist_names=dist_names, parameters=parameters, verbose=True)

    def get_managed_object(self, configuration, mo_id: str):
        return self.netact_interface.get_managed_object(configuration=configuration, mo_id=mo_id)

    def cm_upload(self, mo_dist_name: str):
        return self.netact_interface.upload_configuration(mo_dist_name, timeout=self.cm_upload_timeout)

    def swm_upload(self, mrbts_id: str):
        return self.netact_interface.upload_sw(mrbts_id)

    def import_configuration(self, local_dir, file_name, plan_name, ignore_errors=True):
        self.netact_interface.import_configuration(local_dir=local_dir, plan_name=plan_name, file_name=file_name,
                                                   ignore_errors=ignore_errors)

    def get_actual_config(self):
        return self.netact_interface.get_actual_configuration()

    def delete_plan(self, plan_name, ignore_errors=True):
        self.netact_interface.delete_plan(plan_name, ignore_errors=ignore_errors)

    def provision_plan(self, plan_name):
        self.netact_interface.provision_plan(plan_name)

    def __set_uuf_credentials(self):
        if self.netact_name == "srnclab2001":
            netact_credentials = BuiltIn().get_variable_value("${UUF_NETACT}").get("srnclab2001")
            self.ssh_username = netact_credentials.get("username")
            self.ssh_password = netact_credentials.get('password')

    @retry(times=3, delay=10)
    def setup_ssh_netact_connection(self):
        self.__set_uuf_credentials()
        return self._ssh.connect_to(self.netact_host, self.ssh_username, self.ssh_password)

    def __set_netact_nodes(self):
        if "srnclab" in self.netact_name:
            was_node = self.netact_connection.execute(f"/opt/cpf/sbin/netact_status.sh status service cmwas | "
                                                      f"grep started | grep -E -o '{self.netact_name}node[0-9]{{1,2}}'"
                                                      f"| head -1").strip()
            self.netact_was_node_ip = self.netact_connection.execute(f"host {was_node.strip()} | awk '/has address/ "
                                                                     f"{{print $4}}'").strip()
            self.netact_web_url = f"{self.netact_name}lbwas.srnblr.nsn-rdnet.net"
        elif any(lab in self.netact_name for lab in self.other_netacts):
            self.netact_web_url = f"{self.netact_name}lbwas.{self.netact_name}.srnnam.nsn-rdnet.net"
            self.netact_was_node_ip = self.netact_host
        else:
            raise NotValidNetact(f"Provided Netact: {self.netact_name} is not supported")

    def get_netact_host(self) -> str:
        netact_host = ""
        if "srnclab" in self.netact_name:
            netact_host = subprocess.getoutput(f"host {self.netact_name}node01.srnblr.nsn-rdnet.net | "
                                               f"awk '/has address/ {{print $4}}'")
        elif any(lab in self.netact_name for lab in self.other_netacts):
            netact_host = subprocess.getoutput(f"host vm16.{self.netact_name}.srnnam.nsn-rdnet.net | "
                                               f"awk '/has address/ {{print $4}}'")
        if not netact_host:
            raise Exception("Couldn't get netact host ip")
        return netact_host
